    output = [list(row) for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                left = grid[r][c-1] if c > 0 else None
                right = grid[r][c+1] if c < cols-1 else None

                if left is not None and left != 0 and right is not None and right != 0:
                    output[r][c] = special_color

    return output

